using System;
using System.Collections.Generic;

// PROGRAM: Simulasi Mini Hash Table Berbasis Chaining
public class SimpleHashTable<TKey, TValue> where TKey : notnull
{
    private class Node
    {
        public TKey Key { get; }
        public TValue Value { get; set; }
        public Node? Next { get; set; }
        public Node(TKey key, TValue val, Node? next) => (Key, Value, Next) = (key, val, next);
    }

    private readonly Node?[] _buckets;

    public SimpleHashTable(int bucketCount = 8)
    {
        _buckets = new Node?[bucketCount];
    }

    private int GetBucketIndex(TKey key)
    {
        int hash = key.GetHashCode();
        return Math.Abs(hash) % _buckets.Length;
    }

    public void Put(TKey key, TValue val)
    {
        int idx = GetBucketIndex(key);
        var head = _buckets[idx];

        // Cari apakah key sudah ada (update value)
        for (var curr = head; curr != null; curr = curr.Next)
        {
            if (EqualityComparer<TKey>.Default.Equals(curr.Key, key))
            {
                curr.Value = val;
                return;
            }
        }

        // Chaining: pasang di depan linked list
        _buckets[idx] = new Node(key, val, head);
    }

    public bool TryGet(TKey key, out TValue? val)
    {
        int idx = GetBucketIndex(key);
        for (var curr = _buckets[idx]; curr != null; curr = curr.Next)
        {
            if (EqualityComparer<TKey>.Default.Equals(curr.Key, key))
            {
                val = curr.Value;
                return true;
            }
        }
        val = default;
        return false;
    }
}

public class Program
{
    public static void Main()
    {
        var table = new SimpleHashTable<string, string>(4);
        table.Put("ACC-1", "Budi");
        table.Put("ACC-2", "Siti");

        if (table.TryGet("ACC-1", out string? nama))
        {
            Console.WriteLine($"Ketemu: {nama}");
        }
    }
}

