using System;
using System.Collections.Generic;

public class WordFrequencyAnalyzer
{
    public static Dictionary<string, int> CountWordFrequencies(string?[] words)
    {
        var result = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        if (words == null) return result;

        foreach (var w in words)
        {
            if (string.IsNullOrWhiteSpace(w)) continue;
            string clean = w.Trim();

            if (result.TryGetValue(clean, out int count))
            {
                result[clean] = count + 1;
            }
            else
            {
                result[clean] = 1;
            }
        }

        return result;
    }

    public static void Main()
    {
        string?[] kata = { "Apple", "banana", "apple", "APPLE", "orange", null, " " };
        var freq = CountWordFrequencies(kata);
        Console.WriteLine($"Apple: {freq["apple"]}");
        Console.WriteLine($"Banana: {freq["banana"]}");
    }
}
